/* ===== V119: تعديل أسماء الي يشترون ===== */
function buyersLoad(){ if(Array.isArray(settings.buyers)&&settings.buyers.length){ BUYERS.length=0; settings.buyers.forEach(b=>BUYERS.push(b)) } if(!BUYERS.includes(buyBuyer)) buyBuyer=BUYERS[0] }
function buyWhoRender(){
  buyersLoad(); const seg=document.getElementById('buyWho');
  seg.innerHTML=BUYERS.map(b=>`<button data-b="${esc(b)}" class="${b===buyBuyer?'on':''}">${esc(b)}</button>`).join('')+`<button data-edit="1" class="buy-edit" aria-label="تعديل الأسماء">تعديل</button>`;
  seg.querySelectorAll('button[data-b]').forEach(b=>b.addEventListener('click',()=>{ buyBuyer=b.dataset.b; seg.querySelectorAll('button[data-b]').forEach(x=>x.classList.toggle('on',x===b)) }));
  seg.querySelector('[data-edit]').addEventListener('click',buyersEdit);
}
function buyersEdit(){
  const ov=document.createElement('div'); ov.className='ov'; let list=BUYERS.slice();
  const draw=()=>{ ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true"><div class="dlg-t">أسماء الي يشترون</div>
    <div class="bw-list">${list.map((n,i)=>`<div class="fcount-row"><input data-i="${i}" value="${esc(n)}" aria-label="الاسم"><button class="btn-ghost" data-del="${i}" type="button">احذف</button></div>`).join('')}</div>
    <div class="fcount-row" style="margin-top:10px"><input id="bwNew" placeholder="اسم جديد"><button class="btn-dark" id="bwAdd" type="button">ضيف</button></div>
    <div class="dlg-act"><button class="btn-main" id="bwSave">احفظ</button><button class="btn-ghost" id="bwX">إلغاء</button></div></div>`;
    const read=()=>{ ov.querySelectorAll('[data-i]').forEach(x=>list[+x.dataset.i]=x.value.trim()) };
    ov.querySelectorAll('[data-del]').forEach(b=>b.addEventListener('click',()=>{ read(); if(list.length<2){ toast('لازم يبقى اسم واحد'); return } list.splice(+b.dataset.del,1); draw() }));
    ov.querySelector('#bwAdd').addEventListener('click',()=>{ read(); const v=ov.querySelector('#bwNew').value.trim(); if(!v){ toast('اكتب الاسم'); return } if(list.includes(v)){ toast('موجود'); return } list.push(v); draw() });
    ov.querySelector('#bwX').addEventListener('click',()=>ov.remove());
    ov.querySelector('#bwSave').addEventListener('click',()=>{ read();
      const old=BUYERS.slice(), clean=[...new Set(list.filter(Boolean))]; if(!clean.length){ toast('لازم يبقى اسم واحد'); return }
      /* الاسم المعدل يتعدل بالمسواك القديم هم */
      const ren={}; old.forEach((o,i)=>{ if(list[i]&&list[i]!==o&&i<list.length&&!clean.includes(o)) ren[o]=list[i] });
      const fix=arr=>(arr||[]).forEach(e=>{ if(ren[e.buyer]) e.buyer=ren[e.buyer] });
      if(settings.daily){ fix(settings.daily.items); (settings.daily.history||[]).forEach(h=>fix(h.items)) }
      settings.buyers=clean; if(ren[buyBuyer]) buyBuyer=ren[buyBuyer];
      saveAll(); buyWhoRender(); try{ renderBuy() }catch(_){} ov.remove(); toast('انحفظت الأسماء') });
  };
  draw(); document.body.appendChild(ov);
}

